class BookingSerializer(serializers.Serializer):
    start_date = serializers.DateField()
    end_date = serializers.DateField()
    promo_code = serializers.CharField(required=False)

    # 1. Validate cấp trường (Field-level)
    def validate_promo_code(self, value):
        if value and not PromoCode.objects.filter(code=value, is_active=True).exists():
            raise serializers.ValidationError("Mã khuyến mãi không tồn tại hoặc hết hạn.")
        return value.upper()

    # 2. Validate liên trường (Object-level)
    def validate(self, attrs):
        if attrs['end_date'] < attrs['start_date']:
            raise serializers.ValidationError({"end_date": "Ngày kết thúc không thể trước ngày bắt đầu."})
        return attrs

